result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/wc-copy/src/copy-button.js", "content": "const TEMPLATE = `
  <style>
    :host {
      display: inline-block;
    }
    button {
      font: inherit;
      cursor: pointer;
    }
  </style>
  <button type="button" part="button">Copy</button>
`;

const DEFAULT_LABEL = 'Copy';
const SUCCESS_LABEL = 'Copied';
const FAILURE_LABEL = 'Failed';
const REVERT_DELAY_MS = 2000;

export class CopyButton extends HTMLElement {
  static get observedAttributes() {
    return ['value'];
  }

  #shadowRoot;
  #button;
  #revertTimer = null;

  constructor() {
    super();
    this.#shadowRoot = this.attachShadow({ mode: 'open' });
    this.#shadowRoot.innerHTML = TEMPLATE;
    this.#button = this.#shadowRoot.querySelector('button');
    this.#button.addEventListener('click', () => this.#copy());
  }

  connectedCallback() {
    this.#renderLabel();
  }

  attributeChangedCallback() {
    // Only reflect attribute changes when no explicit property is set.
    if (!this.hasOwnProperty('value')) {
      this.#renderLabel();
    }
  }

  /** `value` property takes precedence over the `value` attribute. */
  get value() {
    if (this.hasOwnProperty('_value')) {
      return this._value;
    }
    return this.getAttribute('value') ?? '';
  }

  set value(v) {
    this._value = v == null ? null : String(v);
    this.#renderLabel();
  }

  get #textToCopy() {
    const text = this.value;
    return typeof text === 'string' ? text : '';
  }

  async #copy() {
    const text = this.#textToCopy;
    try {
      await navigator.clipboard.writeText(text);
      this.#flashLabel(SUCCESS_LABEL);
      this.dispatchEvent(
        new CustomEvent('copy-success', {
          bubbles: true,
          composed: true,
          detail: { text },
        })
      );
    } catch (err) {
      this.#flashLabel(FAILURE_LABEL);
      this.dispatchEvent(
        new CustomEvent('copy-error', {
          bubbles: true,
          composed: true,
          detail: { text, error: err },
        })
      );
    }
  }

  #flashLabel(label) {
    this.#setLabel(label);
    if (this.#revertTimer !== null) {
      clearTimeout(this.#revertTimer);
    }
    this.#revertTimer = setTimeout(() => {
      this.#revertTimer = null;
      this.#renderLabel();
    }, REVERT_DELAY_MS);
  }

  /** Show the value as the label only when it's short enough; otherwise Copy. */
  #renderLabel() {
    if (this.#revertTimer !== null) return;
    this.#setLabel(DEFAULT_LABEL);
  }

  #setLabel(label) {
    this.#button.textContent = label;
  }
}

export function defineCopyButton(tagName = 'copy-button') {
  if (!customElements.get(tagName)) {
    customElements.define(tagName, CopyButton);
  }
  return customElements.get(tagName);
}
"})
