result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/wc-copy/test/copy-button.test.js", "content": "import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { CopyButton, defineCopyButton } from '../src/copy-button.js';

defineCopyButton('copy-button');

function makeButton({ valueAttr = null } = {}) {
  const el = document.createElement('copy-button');
  if (valueAttr !== null) el.setAttribute('value', valueAttr);
  document.body.appendChild(el);
  return el;
}

function getInnerButton(el) {
  return el.shadowRoot.querySelector('button');
}

describe('<copy-button>', () => {
  let writeText;
  let deferred;

  beforeEach(() => {
    vi.useFakeTimers();
    // Controllable clipboard mock: each call returns a promise we resolve/reject manually.
    deferred = [];
    writeText = vi.fn(
      () =>
        new Promise((resolve, reject) => {
          deferred.push({ resolve, reject });
        })
    );
    Object.defineProperty(navigator, 'clipboard', {
      configurable: true,
      value: { writeText },
    });
  });

  afterEach(() => {
    vi.useRealTimers();
    vi.restoreAllMocks();
    document.body.innerHTML = '';
  });

  it('renders a shadow DOM button labeled "Copy"', () => {
    const el = makeButton();
    expect(el.shadowRoot).toBeTruthy();
    const btn = getInnerButton(el);
    expect(btn).toBeTruthy();
    expect(btn.textContent).toBe('Copy');
  });

  it('copies the attribute value on click and dispatches copy-success with the text', async () => {
    const el = makeButton({ valueAttr: 'hello world' });

    const seen = [];
    el.addEventListener('copy-success', (e) => seen.push(e));

    getInnerButton(el).click();

    expect(writeText).toHaveBeenCalledTimes(1);
    expect(writeText).toHaveBeenCalledWith('hello world');

    deferred[0].resolve();
    await Promise.resolve(); // flush microtasks so the promise chain settles

    expect(seen.length).toBe(1);
    const event = seen[0];
    expect(event.type).toBe('copy-success');
    expect(event.bubbles).toBe(true);
    expect(event.composed).toBe(true);
    expect(event.detail.text).toBe('hello world');
  });

  it('swaps label to "Copied" then reverts to "Copy" after 2 seconds', async () => {
    const el = makeButton({ valueAttr: 'abc' });
    const btn = getInnerButton(el);
    btn.click();
    deferred[0].resolve();
    await Promise.resolve();

    expect(btn.textContent).toBe('Copied');

    vi.advanceTimersByTime(1999);
    expect(btn.textContent).toBe('Copied');

    vi.advanceTimersByTime(1);
    expect(btn.textContent).toBe('Copy');
  });

  it('shows "Failed" and dispatches copy-error when the clipboard rejects', async () => {
    const el = makeButton({ valueAttr: 'nope' });

    const seen = [];
    el.addEventListener('copy-error', (e) => seen.push(e));

    getInnerButton(el).click();
    deferred[0].reject(new Error('denied'));
    await Promise.resolve();

    expect(getInnerButton(el).textContent).toBe('Failed');

    expect(seen.length).toBe(1);
    const event = seen[0];
    expect(event.type).toBe('copy-error');
    expect(event.bubbles).toBe(true);
    expect(event.composed).toBe(true);
    expect(event.detail.text).toBe('nope');
  });

  it('reverts the "Failed" label back to "Copy" after 2 seconds', async () => {
    const el = makeButton({ valueAttr: 'x' });
    const btn = getInnerButton(el);
    btn.click();
    deferred[0].reject(new Error('no'));
    await Promise.resolve();

    expect(btn.textContent).toBe('Failed');
    vi.advanceTimersByTime(2000);
    expect(btn.textContent).toBe('Copy');
  });

  describe('value property takes precedence over value attribute', () => {
    it('property wins when both are set', async () => {
      const el = makeButton({ valueAttr: 'from-attribute' });
      el.value = 'from-property';

      getInnerButton(el).click();
      deferred[0].resolve();
      await Promise.resolve();

      expect(writeText).toHaveBeenCalledWith('from-property');
    });

    it('property is used even without an attribute', () => {
      const el = makeButton();
      el.value = 'prop-only';
      getInnerButton(el).click();
      expect(writeText).toHaveBeenCalledWith('prop-only');
    });

    it('falls back to the attribute once the property is cleared', () => {
      const el = makeButton({ valueAttr: 'attr' });
      el.value = 'prop';
      el.value = null; // clear own property

      getInnerButton(el).click();
      expect(writeText).toHaveBeenCalledWith('attr');
    });

    it('reflects later attribute changes while no property is set', () => {
      const el = makeButton();
      el.setAttribute('value', 'updated');
      getInnerButton(el).click();
      expect(writeText).toHaveBeenCalledWith('updated');
    });
  });
});
"})
